      "title": "Cross-reference to non-existent section 9.4.2",
      "page": 61,
      "quote": "per Section 9.4.2",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 9.5.1 for laboratory severity",
      "page": 62,
      "quote": "Evaluation of severity of laboratory abnormalities will be assessed according to the scale outlined in Section 9.5.1.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 4.2.1 and 4.2.2",
      "page": 68,
      "quote": "The assessment of primary and secondary endpoints specified in Section 4.2.1 and Section 4.2.2",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 4.4",
      "page": 70,
      "quote": "The ADA variables described in Section 4.4",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section 16.1",
      "page": 71,
      "quote": "Investigator and sponsor responsibilities surrounding the premature termination of a study are presented in Section 16.1.",
      "severity": "major"
    },
    {
      "title": "Inconsistent definition of treatment-emergent period",
      "page": 68,
      "quote": "The treatment-emergent period is defined as the day from first dose of study drug to the end of study.  The treatment-emergent period includes the 16-week treatment period and follow-up period.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of follow-up period",
      "page": 68,
      "quote": "Follow-up period:  date after week 16 visit date (study day 113 starting from first dose of study drug if week 16 visit date is unavailable) to EOS visit.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of treatment period",
      "page": 68,
      "quote": "Treatment period:  date of the first dose of study drug to week 16 visit date (study day 113 starting from the first dose of study drug if week 16 visit date is unavailable) or ET date, whichever comes first.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of baseline",
      "page": 71,
      "quote": "The baseline assessment will be the latest, valid pre-first-dose assessment available.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of treatment-emergent AESI",
      "page": 69,
      "quote": "Treatment-emergent AESIs (defined with a PT or a prespecified grouping)",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of treatment compliance",
      "page": 70,
      "quote": "Treatment compliance= (number of investigational product injections during exposure period)/(number of planned investigational product injections during exposure period) × 100%",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of duration of exposure",
      "page": 70,
      "quote": "The duration of exposure during the study will be presented by treatment and calculated as: (date of last study drug injection – date of first study drug injection) + 14 days",
      "severity": "minor"
    }
  ]
}
